//! Pure tests against tests/vectors.json (generated by game/scripts/gen-shard-vectors.mjs from the JavaScript
//! twin): token id, SVG, media data URI, media hash, title, description and extra must match byte for byte;
//! every invalid case must be rejected.

use crate::image::{metadata_parts, svg, ShardData};
use near_sdk::serde::Deserialize;
use near_sdk::serde_json::{self, Value};

const VECTORS: &str = include_str!("../tests/vectors.json");

#[derive(Deserialize)]
#[serde(crate = "near_sdk::serde")]
struct Metadata {
    title: String,
    description: String,
    media: String,
    media_hash: String,
    extra: String,
}

#[derive(Deserialize)]
#[serde(crate = "near_sdk::serde")]
#[serde(rename_all = "camelCase")]
struct ShardVector {
    input: ShardData,
    token_id: String,
    svg: String,
    svg_sha256: String,
    metadata: Metadata,
}

#[derive(Deserialize)]
#[serde(crate = "near_sdk::serde")]
struct Invalid {
    why: String,
    data: Value,
}

#[derive(Deserialize)]
#[serde(crate = "near_sdk::serde")]
struct Vectors {
    spec: String,
    shards: Vec<ShardVector>,
    invalid: Vec<Invalid>,
}

fn vectors() -> Vectors {
    serde_json::from_str(VECTORS).expect("vectors.json parses")
}

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

#[test]
fn spec_matches() {
    assert_eq!(vectors().spec, crate::image::SPEC);
    assert!(vectors().shards.len() >= 8);
}

#[test]
fn every_vector_shard_validates_and_reproduces_token_id_and_svg() {
    for v in vectors().shards {
        v.input.validate().unwrap_or_else(|e| panic!("{}: {e}", v.token_id));
        assert_eq!(v.input.token_id(), v.token_id);
        let image = svg(&v.input);
        assert_eq!(image, v.svg, "svg of {}", v.token_id);
        assert_eq!(hex(&near_sdk::env::sha256(image.as_bytes())), v.svg_sha256, "svg hash of {}", v.token_id);
    }
}

#[test]
fn every_vector_shard_reproduces_the_metadata() {
    use near_sdk::base64::Engine as _;
    for v in vectors().shards {
        let m = metadata_parts(&v.input);
        assert_eq!(m.title, v.metadata.title, "title of {}", v.token_id);
        assert_eq!(m.description, v.metadata.description, "description of {}", v.token_id);
        assert_eq!(m.media, v.metadata.media, "media of {}", v.token_id);
        assert_eq!(near_sdk::base64::engine::general_purpose::STANDARD.encode(&m.media_hash.0), v.metadata.media_hash, "media_hash of {}", v.token_id);
        assert_eq!(m.extra, v.metadata.extra, "extra of {}", v.token_id);
        // extra round-trips to the same data
        let back: ShardData = serde_json::from_str(&m.extra).unwrap();
        assert_eq!(back, v.input);
    }
}

#[test]
fn every_invalid_vector_is_rejected() {
    for bad in vectors().invalid {
        match serde_json::from_value::<ShardData>(bad.data.clone()) {
            Ok(d) => assert!(d.validate().is_err(), "accepted invalid case: {}", bad.why),
            Err(_) => {} // does not even deserialise (e.g. weight 5 fits u8, but shard_id 0 is caught by validate; a negative would fail here)
        }
    }
}

#[test]
fn svg_is_well_formed_and_small() {
    for v in vectors().shards {
        let image = svg(&v.input);
        assert!(image.starts_with("<svg xmlns=\"http://www.w3.org/2000/svg\""));
        assert!(image.ends_with("</svg>"));
        assert!(image.len() < 2200, "svg of {} is {} bytes", v.token_id, image.len());
        assert_eq!(image.matches("<line ").count(), 8);
        assert_eq!(image.matches("r=\"7\"").count(), v.input.weight as usize);
    }
}
